# Read only - Microsoft's script from Learn, shortened. Needs only Microsoft.Graph.Authentication.
Connect-MgGraph -Scopes 'EntitlementManagement.Read.All' -NoWelcome
$found = New-Object System.Collections.Generic.List[object]
$uri = 'https://graph.microsoft.com/v1.0/identityGovernance/entitlementManagement/assignmentPolicies?$expand=accessPackage&$top=50'
while ($uri) {
    $page = Invoke-MgGraphRequest -Method GET -Uri $uri
    foreach ($policy in $page.value) {
        if (-not $policy.automaticRequestSettings) { continue }   # only automatic assignment policies
        foreach ($target in @($policy.specificAllowedTargets)) {
            if ([string]$target.'@odata.type' -notlike '*attributeRuleMembers*') { continue }
            if ([string]$target.membershipRule -match '(?i)memberof') {
                $found.Add([pscustomobject]@{ AccessPackage = $policy.accessPackage.displayName; Policy = $policy.displayName; PolicyId = $policy.id; Rule = $target.membershipRule })
            }
        }
    }
    $uri = $page.'@odata.nextLink'
}
$found | Format-Table AccessPackage, Policy, Rule -AutoSize

# Read only. Run after the first block: one CSV row per member of every memberOf group.
$rows = foreach ($g in $memberOf) {
    Get-MgGroupMember -GroupId $g.Id -All | ForEach-Object {
        [pscustomobject]@{ Group = $g.DisplayName; GroupId = $g.Id; MemberId = $_.Id
            Name = $_.AdditionalProperties['displayName']; UPN = $_.AdditionalProperties['userPrincipalName'] }
    }
}
$rows | Export-Csv -Path .\memberof-members-$(Get-Date -Format yyyyMMdd).csv -NoTypeInformation -Encoding UTF8

# Read only. Lists every app granted an application permission on the two legacy APIs the retirement covers.
Connect-MgGraph -Scopes 'Application.Read.All' -NoWelcome
foreach ($name in 'WindowsDefenderATP', 'Microsoft Threat Protection') {
    $api = Get-MgServicePrincipal -Filter "displayName eq '$name'" -Property Id, DisplayName, AppRoles
    if (-not $api) { continue }
    $roles = @{}; $api.AppRoles | ForEach-Object { $roles[$_.Id] = $_.Value }
    Get-MgServicePrincipalAppRoleAssignedTo -ServicePrincipalId $api.Id -All |
        Where-Object { $roles[$_.AppRoleId] -match 'Advanced' } |
        Select-Object @{n='Api';e={$name}}, PrincipalDisplayName, PrincipalId, @{n='Permission';e={$roles[$_.AppRoleId]}}, CreatedDateTime
}

# Read only. The Graph replacement for the legacy advanced hunting API call.
Connect-MgGraph -Scopes 'ThreatHunting.Read.All' -NoWelcome
$params = @{
    Query    = 'DeviceProcessEvents | where InitiatingProcessFileName =~ "powershell.exe" | project Timestamp, FileName, InitiatingProcessFileName | order by Timestamp desc | limit 10'
    Timespan = 'P7D'
}
$r = Start-MgSecurityHuntingQuery -BodyParameter $params
$r.Results | ForEach-Object { $_.AdditionalProperties }
